<?php $deviceStateText = ['registered'=>'Registrované','registering'=>'Zapisuje se','pending'=>'Čeká','incomplete'=>'Neúplné','blocked'=>'Zakázané'][$device['registration_state']] ?? $device['registration_state']; ?>
<section class="page-intro device-detail-intro"><div><a class="back-link" href="<?= e(url('/devices')) ?>">← Registrovaná zařízení</a><p><?= e($device['person_name'] ?: 'Bez držitele') ?> · <span class="mono"><?= e($device['mac_address']) ?></span></p></div><div class="page-actions"><span class="badge <?= e($device['registration_state']) ?>"><i></i><?= e($deviceStateText) ?></span><?php if ((int) $device['online'] === 1): ?><span class="badge registered"><i></i>Online</span><?php endif; ?><?php if ($auth->isAdmin()): ?><form method="post" action="<?= e(url('/devices/repair')) ?>" data-confirm="Obnovit konfiguraci Access Listu, DHCP a Simple Queue podle WiFi Manageru?"><?= csrf_field() ?><input type="hidden" name="device_id" value="<?= (int) $device['id'] ?>"><button class="button subtle" type="submit"><?= icon('refresh') ?> Opravit konfiguraci</button></form><?php endif; ?></div></section>

<?php if (is_private_mac($device['mac_address'])): ?><div class="info-banner warning"><?= icon('alert') ?><div><strong>Zařízení používá soukromou MAC adresu</strong><p>Pokud telefon začne adresu pravidelně měnit, bude se hlásit jako nové zařízení. V nastavení této Wi‑Fi je vhodná pevná soukromá adresa.</p></div></div><?php endif; ?>

