<?php foreach ($flows['rows'] as $row): ?><tr><td class="mono"><?= e(format_datetime($row['first_at'])) ?></td><td class="mono"><?= e($row['source_ip']) ?><?= $row['source_port']?':'.(int)$row['source_port']:'' ?></td><td class="flow-arrow"><?= icon('arrow-right') ?></td><td class="mono"><?= e($row['destination_ip']) ?><?= $row['destination_port']?':'.(int)$row['destination_port']:'' ?></td><td><span class="protocol-pill"><?= e($row['protocol'] ?: '—') ?></span></td><td><strong><?= e(format_bytes($row['bytes'])) ?></strong><small class="subline"><?= number_format((int)$row['packets'],0,',',' ') ?> paketů</small></td></tr><?php endforeach; ?>
</tbody></table></div></section>
